pub(crate) fn normalize_root(root: &str) -> String {
    let r = root.replace('\\', "/");
    let mut out = String::with_capacity(r.len());
    let mut prev = false;
    for c in r.chars() {
        if c == '/' {
            if !prev {
                out.push(c);
            }
            prev = true;
        } else {
            out.push(c);
            prev = false;
        }
    }
    out.trim_end_matches('/').to_string()
}
